import csv
from collections import defaultdict

targets = {
 'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8':'F3_Z01',
 '7a9e6dea-7214-57d7-a3ab-6fec741ab22a':'F1_Z01',
 'baef86cb-2941-5d61-87b0-ffa91d79f23a':'F2_Z01',
 '14a08406-79a0-52ca-b8a1-8563259dc820':'F4_Z01',
 '2747096d-e7c5-5b14-b6e1-ff12157886ed':'F4_Z02',
 'bcc5a78f-36a4-55a0-9420-7a80fc9b2deb':'F3_Z02',
 '9c6223f8-3611-5ceb-9107-70e8206e9ccd':'F3_Z03',
 'c49bbc2f-096e-5e16-bead-066250790308':'F3_Z05',
}

data=defaultdict(dict)
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        if r['timeseries_id'] in targets:
            data[r['timeseries_id']][r['timestamp']]=float(r['value'])

# monthly means by zone; check 2018 Jul-Dec vs 2019 monthly
def monthly(ts):
    d=data[ts]
    by=defaultdict(list)
    for t,v in d.items():
        ym=t[:7]
        by[ym].append(v)
    return {ym:sum(v)/len(v) for ym,v in by.items()}

zones={name:monthly(ts) for ts,name in targets.items()}
months=sorted(zones['F3_Z01'].keys())
print("zone        "+" ".join(m for m in months))
for name,m in zones.items():
    print(f"{name:8s} "+" ".join(f"{m.get(x,0):6.2f}" for x in months))
